-- PT118-S1-Q9. Batch 09.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch09$PT118-S1-Q9$batch09$ AND q.stimulus=$batch09$The use of phrases like “as so-and-so said” or “as the saying goes” suggests that the quote that follows has just been illustrated. Such phrases are inappropriately used when an apparent counterexample has just been given.$batch09$ AND q.prompt=$batch09$Which one of the following contains an inappropriate usage of a phrase, according to the principle stated above?$batch09$ AND q.correct_choice=$batch09$E$batch09$) THEN RAISE EXCEPTION 'Question changed: PT118-S1-Q9'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanation_steps s WHERE s.explanation_id=$batch09$729c3586-c0e3-467a-bf5b-e4777357a59f$batch09$) <> 3 OR (SELECT COUNT(*) FROM lr_explanation_choice_notes n WHERE n.explanation_id=$batch09$729c3586-c0e3-467a-bf5b-e4777357a59f$batch09$) <> 0 THEN RAISE EXCEPTION 'Explanation changed: PT118-S1-Q9'; END IF; END $guard$;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch09$A$batch09$, $batch09$Fatima knows enough mathematics to see how much will stay unsolved. That's the saying in action: you need to know a lot before you see how little you know. The story illustrates it, so the phrase is used properly.$batch09$), ($batch09$B$batch09$, $batch09$Harold has done the same thing many times before. That's selfishness as predictable as gravity, so the quote matches the story. The friends' surprise doesn't change that Harold's behavior was calculable.$batch09$), ($batch09$C$batch09$, $batch09$Roger won't spend the money because Roger is frugal. "A penny saved is a penny earned" is the frugal person's motto. The story illustrates it.$batch09$), ($batch09$D$batch09$, $batch09$Sharon loves cats, and Sharon's husband, despite the allergy, still sometimes comes along to cat shows. Sharing a life with Sharon means sharing what Sharon loves, at least a little. The story illustrates the saying.$batch09$), ($batch09$E$batch09$, $batch09$Raoul's trip ended with a broken leg and two weeks in the hospital. That didn't end well, so "All's well that ends well" has no illustration here. The story is an apparent counterexample, and putting "as the saying goes" after it is the misuse the principle describes.$batch09$)) v(letter,body) WHERE q.qid=$batch09$PT118-S1-Q9$batch09$ AND e.id=$batch09$729c3586-c0e3-467a-bf5b-e4777357a59f$batch09$ AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
